package com.vit.archds.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*; import java.util.function.Function;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long exp){if(secret.length()<32) throw new IllegalArgumentException("JWT secret must be at least 32 characters"); key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));expiration=exp;} public String generate(UserDetails u){Date now=new Date(),exp=new Date(now.getTime()+expiration);return Jwts.builder().subject(u.getUsername()).issuedAt(now).expiration(exp).signWith(key).compact();} public String extractUsername(String token){return extract(token,Claims::getSubject);} public boolean valid(String token,UserDetails u){try{return u.getUsername().equals(extractUsername(token))&&!extract(token,Claims::getExpiration).before(new Date());}catch(JwtException|IllegalArgumentException e){return false;}} private <T>T extract(String t,Function<Claims,T> r){return r.apply(Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload());}}
